          <h2 className="text-2xl font-bold mb-4">MarketLab</h2>
          <p className="text-gray-400 mb-6">Please log in to view your dashboard</p>
          <button className="btn-primary">Go to Login</button>
        </div>
      </div>
    );
  }

  const mockData: MarketOverviewItem[] = [
    {
      symbol: "RELIANCE",
      name: "Reliance Industries",
      price: 2845.35,
      change: 52.15,
      changePercent: 1.87,
      volume: 12548920,
    },
    {
      symbol: "TCS",
      name: "Tata Consultancy Services",
      price: 3892.10,
      change: -38.45,
      changePercent: -0.98,
      volume: 8765432,
    },
    {
      symbol: "HDFCBANK",
      name: "HDFC Bank",
      price: 1624.80,
      change: 15.20,
      changePercent: 0.94,
      volume: 45678901,
    },
  ];

  const marketStatus = marketData?.status || "CLOSED";

  return (
    <div className="p-4 md:p-6">
      <header className="mb-6">
        <h1 className="text-3xl font-bold">MarketLab</h1>
        <p className="text-gray-400">Your full-stack stock market platform</p>
      </header>

      {user && (
        <Card className="mb-6">
          <h2 className="text-xl font-semibold mb-4">Market Status</h2>
          <div className="grid grid-cols-2 gap-4">
            <div>
              <h3>NSE</h3>
              <p className={marketStatus === "OPEN" ? "text-green-400" : "text-red-400"}>
                {marketStatus}
              </p>
              {marketData?.indexValues && (
                <div>
                  <p>Nifty 50: {marketData.indexValues.nifty50?.toLocaleString() || "-"}</p>
                  <p>Sensex: {marketData.indexValues.sensex?.toLocaleString() || "-"}</p>
                </div>
              )}
            </div>
            <div>
              <h3>BSE</h3>
              <p className={marketStatus === "OPEN" ? "text-green-400" : "text-red-400"}>
                {marketStatus}
              </p>
            </div>
          </div>
          {isPending && (
            <p className="text-sm text-gray-500 mt-2">Loading market data...</p>
          )}
        </Card>
      )}

      <Card className="mb-6">
        <h2 className="text-xl font-semibold mb-4">Market Overview</h2>
        <Grid cols={2} gap={4}>
          {mockData.map((item) => (
            <div key={item.symbol} className="p-4 rounded-lg border">
              <h3 className="text-sm text-gray-400 mb-1">{item.symbol}</h3>
              <p className="text-2xl font-bold {
                item.change > 0 ? "text-green-400" : "text-red-400"
              }">
                {item.price.toLocaleString()}
              </p>
              <p className="text-sm {
                item.change > 0 ? "text-green-400" : "text-red-400"
              }">
                {item.change.toFixed(2)} ({item.changePercent.toFixed(2)}%)
              </p>
            </div>
          ))}
        </Grid>
        {isPending && (
          <p className="text-sm text-gray-500 mt-2">Loading...</p>
        )}
      </Card>

      <div className="mt-6 grid grid-cols-2 gap-3">
        <Button variant="primary" onClick={() => console.log("Watchlists")}>
          Watchlists
        </Button>
        <Button variant="secondary" onClick={() => console.log("Screener")}>
          Stock Screener
        </Button>
        <Button variant="primary" onClick={() => console.log("Charts")}>
          Charts
        </Button>
        <Button variant="secondary" onClick={() => console.log("Trading")}>
          Trading
        </Button>
      </div>
    </div>
  );
};

export default Dashboard;"}}


