import ReactDOM from "react-dom/client";
import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import { ConvexReactClient } from "convex/react";
import { ConvexAuthProvider } from "@convex-dev/auth/react";
import App from "./App";
import "./styles/globals.css";

const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      retry: 1,
      staleTime: 30_000,
    },
  },
});

const convexUrl = import.meta.env.VITE_CONVEX_URL;

if (!convexUrl) {
  ReactDOM.createRoot(document.getElementById("root")!).render(
    <div style={{ padding: 32, fontFamily: "system-ui", color: "#e8e8f0", background: "#0a0a0f", minHeight: "100vh" }}>
      <h1>Configuration required</h1>
      <p>
        <code>VITE_CONVEX_URL</code> is not set. Run <code>npx convex dev</code> in the{" "}
        <code>marketlab/</code> directory to configure a Convex deployment, then restart{" "}
        <code>npm run dev</code>.
      </p>
    </div>
  );
} else {
  const convex = new ConvexReactClient(convexUrl);

  ReactDOM.createRoot(document.getElementById("root")!).render(
    <React.StrictMode>
      <ConvexAuthProvider client={convex}>
        <QueryClientProvider client={queryClient}>
          <App />
        </QueryClientProvider>
      </ConvexAuthProvider>
    </React.StrictMode>
  );
}
