import React from "react";
import ReactDOM from "react-dom/client";
import "./styles/globals.css";
import PriceChart from "./components/chart/PriceChart";
import DataModeBadge from "./components/market/DataModeBadge";
import { sampleCandles } from "@quant/sample";
import { istDateToUtcMs } from "@quant/time";
import type { Candle, Interval } from "./lib/marketClient";

const interval: Interval = "1d";
const raw = sampleCandles({
  symbol: "SBIN",
  interval,
  fromMs: istDateToUtcMs("2024-01-01"),
  toMs: istDateToUtcMs("2024-06-28"),
});
const candles: Candle[] = raw.map((row) => ({ ...row, instrumentId: "NSE:SBIN:EQUITY" }));

const App: React.FC = () => (
  <div className="p-6">
    <header className="mb-4 flex items-center gap-3">
      <h1 className="text-2xl font-bold">SBIN</h1>
      <DataModeBadge mode="SAMPLE" source="sample" />
      <DataModeBadge mode="LIVE" source="fyers" />
      <DataModeBadge mode="CACHED" />
    </header>

    <PriceChart
      title="SBIN · 1D"
      subtitle={`${candles.length} sample candles`}
      candles={candles}
      interval={interval}
      chartType="candlestick"
      indicators={[
        { name: "SMA", enabled: true, period: 20 },
        { name: "BOLLINGER", enabled: true, period: 20, multiplier: 2 },
        { name: "RSI", enabled: true, period: 14 },
      ]}
      mode="SAMPLE"
      source="sample"
      height={420}
    />
  </div>
);

ReactDOM.createRoot(document.getElementById("root")!).render(<App />);
"}}


