    const byId = new Map(result.quotes.map((quote) => [quote.instrumentId, quote]));
    const observations: {
      alertId: Id<"priceAlerts">;
      price: number;
      mode: "LIVE" | "DELAYED" | "CACHED" | "HISTORICAL" | "SAMPLE";
      source: string;
      crossed: boolean;
    }[] = [];

    let skippedNoPrice = 0;
    let sampleEvaluated = 0;
    let sampleCrossed = 0;
    for (const alert of alerts) {
      const quote = byId.get(alert.instrumentId);
      if (!quote || !Number.isFinite(quote.lastPrice) || quote.lastPrice <= 0) {
        skippedNoPrice += 1;
        continue;
      }
      const crossed =
        alert.direction === "ABOVE"
          ? quote.lastPrice >= alert.threshold
          : quote.lastPrice <= alert.threshold;
      if (quote.mode === "SAMPLE") {
        sampleEvaluated += 1;
        if (crossed) sampleCrossed += 1;
      }
      observations.push({
        alertId: alert._id,
        price: quote.lastPrice,
        mode: quote.mode,
        source: quote.source,
        crossed,
      });
    }

    const triggered = await ctx.runMutation(internal.alerts.applyEvaluation, {
      userId,
      nowMs: asOf,
      observations,
    });

    return {
      evaluated: observations.length,
      triggered,
      skippedNoPrice,
      sampleEvaluated,
      triggeredSample: sampleCrossed,
      asOf,
      note: result.warning ?? result.note ?? null,
