      .fn()
      .mockResolvedValue(
        jsonResponse({
          s: "ok",
          candles: [
            [1700100000, 110, 115, 105, 112, 900],
            [1700000000, 100, 105, 95, 102, 800],
            [1700200000, "bad", 1, 1, 1, 1],
          ],
