+
+describe("Breeze adapter contract", () => {
+  it("reports every required secret by name", () => {
+    const { configured, missing } = breeze.isConfigured({});
+    expect(configured).toBe(false);
+    expect(missing).toEqual([
+      "BREEZE_APP_KEY",
+      "BREEZE_SECRET_KEY",
+      "BREEZE_SESSION_TOKEN",
